  ["\\{x : x \\text{ is a natural number}, x < 4\\}",{1,2,3},4,{0,1,2,3},[[4,true,"It includes 0, which is not a natural number."],[0,false,"Nothing: the list is correct."],[1,false,"It includes an end value that the rule leaves out."],[2,false,"It leaves out an end value that the rule includes."],[3,false,"It includes 1, which is not a prime number."]],1,{1,3},{1,2,3,103},{1,3,1000},"\\(0\\) is not a natural number: the natural numbers start at \\(1\\)."],
